import type { WorkflowModule, WorkflowRunOptions } from '@harms-haus/engin';
import { createHarness, loadProfilesFromDirs, resolveProfilesDirs } from '@harms-haus/engin';

// ─── Phases ─────────────────────────────────────────────────────────────────

const DEVELOP_PHASES = [
  { id: 'initialization', label: 'Initialization', icon: '🔧' },
  { id: 'scouting', label: 'Scouting', icon: '🔍' },
  { id: 'scouting_review', label: 'Scouting Review', icon: '📋' },
  { id: 'planning', label: 'Planning', icon: '📝' },
  { id: 'plan_review', label: 'Plan Review', icon: '👀' },
  { id: 'implementing', label: 'Implementing', icon: '🔨' },
  { id: 'final_review', label: 'Final Review', icon: '✅' },
  { id: 'done', label: 'Done', icon: '🎉' },
];

// ─── Workflow Module ────────────────────────────────────────────────────────

export default {
  name: 'develop',
  description: 'Multi-agent development workflow',

  async run(taskPrompt: string, options: WorkflowRunOptions): Promise<void> {
    const { onStatus } = options;

    // 1. Declare phases to frontend
    onStatus?.onSidebarUpdate?.({ phases: DEVELOP_PHASES });

    // 2. Signal workflow start
    onStatus?.onWorkflowStart?.({
      taskPrompt,
      resumed: false,
      workDir: options.workDir,
    });

    // ── Phase: initialization ──────────────────────────────────────────────
    onStatus?.onPhaseStart?.({ phase: 'initialization', round: 1 });

    // Generate a concise title using the pi agent
    let title: string;
    try {
      const profilesDirs = resolveProfilesDirs(options.cwd, 'develop');
      const profiles = await loadProfilesFromDirs(profilesDirs);
      const profile = profiles.values().next().value;

      if (profile) {
        const harness = createHarness({
          profile,
          cwd: options.cwd,
          apiKeys: options.apiKeys,
          onAgentStatus: {
            onTurnStart: (info) => onStatus?.onTurnStart?.(info),
            onTurnEnd: (info) => onStatus?.onTurnEnd?.(info),
            onToolCallStart: (info) => onStatus?.onToolCallStart?.(info),
            onToolCallEnd: (info) => onStatus?.onToolCallEnd?.(info),
          },
        });

        onStatus?.onAgentSpawn?.({
          agentId: 'title-generator',
          profile: profile.id,
          phase: 'initialization',
        });

        const { session, dispose } = await harness;

        await session.prompt(
          'Generate a concise title (3-6 words) summarizing this task. Return ONLY the title:\n\n' +
            taskPrompt,
        );

        const responseText = session.getLastAssistantText() ?? '';
        title = responseText.trim();

        dispose();

        onStatus?.onAgentComplete?.({
          agentId: 'title-generator',
          profile: profile.id,
          phase: 'initialization',
        });
      } else {
        title = taskPrompt.slice(0, 50) + '...';
      }
    } catch {
      title = taskPrompt.slice(0, 50) + '...';
    }

    // Update sidebar with generated title and initialization indicator
    onStatus?.onSidebarUpdate?.({ title, indicator: '🔧' });
    onStatus?.onPhaseComplete?.({ phase: 'initialization', durationMs: 0 });

    // ── Remaining phases (stubs for future work) ──────────────────────────
    const remainingPhases = DEVELOP_PHASES.filter(
      (p) => p.id !== 'initialization' && p.id !== 'done',
    );

    for (const phase of remainingPhases) {
      onStatus?.onPhaseStart?.({ phase: phase.id, round: 1 });
      onStatus?.onSidebarUpdate?.({ indicator: phase.icon });

      // Simulate minimal processing delay
      await new Promise((resolve) => setTimeout(resolve, 50));

      onStatus?.onPhaseComplete?.({ phase: phase.id, durationMs: 0 });
    }

    // ── Phase: done ────────────────────────────────────────────────────────
    onStatus?.onPhaseStart?.({ phase: 'done', round: 1 });
    onStatus?.onSidebarUpdate?.({ indicator: '🎉' });
    onStatus?.onPhaseComplete?.({ phase: 'done', durationMs: 0 });

    // ── Signal workflow complete ───────────────────────────────────────────
    onStatus?.onWorkflowComplete?.({ totalDurationMs: 0, agentCount: 1 });
  },
} satisfies WorkflowModule;

// ─── Core ───────────────────────────────────────────────────────────────────
export * from './core/agent-loop.js';
export * from './core/auth.js';
export * from './core/config.js';
export * from './core/harness-factory.js';
export * from './core/profile.js';
export * from './core/session-history.js';
export * from './core/structured-output.js';
export * from './core/types.js';
export * from './core/utils.js';
export * from './core/workflow-loader.js';
export * from './setup.js';

// ─── Tracking ───────────────────────────────────────────────────────────────
export * from './tracking/audit-log.js';
export * from './tracking/task-status.js';
export * from './tracking/workflow-status.js';

// ─── Pool ────────────────────────────────────────────────────────────────
export * from './pool/index.js';

// ─── Re-exports from @earendil-works/pi-coding-agent ───────────────────────
export { AgentSession, AuthStorage, DefaultResourceLoader, SessionManager } from '@earendil-works/pi-coding-agent';
export type { ThinkingLevel };

// ─── Peer dependency re-exports (not re-exported by pi-coding-agent) ───────
import type { ThinkingLevel } from '@earendil-works/pi-agent-core';

export { getModel, parseJsonWithRepair } from '@earendil-works/pi-ai';
export type { Model } from '@earendil-works/pi-ai';

// ─── Agent Profile ──────────────────────────────────────────────────────────
export interface AgentProfile {
  id: string;
  name: string;
  provider: string;
  model: string;
  thinkingLevel: ThinkingLevel;
  systemPrompt: string;
  excludeTools: string[];
  includeTools: string[];
}

// ─── Task Tracking ──────────────────────────────────────────────────────────
export type TaskStatus = 'blocked' | 'ready' | 'claimed' | 'implementing' | 'reviewing' | 'done';

export interface Task {
  id: string;
  title: string;
  prompt: string;
  profile: string;
  files: string[];
  dependencies: string[];
  status: TaskStatus;
  assignedAgent?: string;
  result?: unknown;
  reviewFeedback?: string;
  isCode?: boolean;
}

// ─── Workflow Phases ────────────────────────────────────────────────────────
export type WorkflowPhase =
  | 'scouting'
  | 'scouting_review'
  | 'planning'
  | 'plan_review'
  | 'implementing'
  | 'final_review'
  | 'done';

export interface WorkflowState {
  taskPrompt: string;
  currentPhase: WorkflowPhase;
  completedPhases: WorkflowPhase[];
  tasks: Task[];
  /** Scouting reports stored as opaque values; consumers should cast to their specific schema type */
  scoutingReports: unknown[];
  /** Plan stored as opaque value; consumers should cast to their specific schema type */
  plan: unknown;
  research?: string;
  /** Plan review feedback text from the reviewer when a plan is rejected */
  planReviewFeedback?: string;
  /** Specific improvement suggestions from the plan reviewer */
  planReviewSuggestions?: string[];
  stats: {
    totalTokens: number;
    totalCost: number;
    agentCount: number;
  };
}

// ─── Audit Events ───────────────────────────────────────────────────────────
export type AuditEvent =
  | { type: 'agent_start'; agentId: string; profile: AgentProfile; taskId?: string; timestamp: string }
  | { type: 'agent_end'; agentId: string; result: unknown; taskId?: string; timestamp: string }
  | { type: 'decision'; agentId: string; decision: string; reasoning: string; taskId?: string; timestamp: string }
  | { type: 'structured_output'; agentId: string; output: unknown; taskId?: string; timestamp: string }
  | { type: 'error'; agentId: string; error: string; taskId?: string; timestamp: string };

// ─── Structured Output ──────────────────────────────────────────────────────
export interface StructuredOutputOptions {
  maxRetries: number;
  retryPrompt?: string;
}

// ─── Status Callbacks ──────────────────────────────────────────────────────
export interface WorkflowStatusCallbacks {
  onWorkflowStart?: (info: { taskPrompt: string; resumed: boolean; workDir: string }) => void;
  onPhaseStart?: (info: { phase: string; round: number }) => void;
  onPhaseComplete?: (info: { phase: string; durationMs: number }) => void;
  onAgentSpawn?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onAgentComplete?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onTaskStart?: (info: { taskId: string; title: string; agentId: string }) => void;
  onTaskComplete?: (info: { taskId: string; title: string }) => void;
  onTaskRejected?: (info: { taskId: string; title: string; reason: string }) => void;
  onDecision?: (info: { agentId: string; decision: string; reasoning: string; taskId?: string }) => void;
  onError?: (info: { agentId: string; error: string; phase: string; taskId?: string }) => void;
  onWorkflowComplete?: (info: { totalDurationMs: number; agentCount: number }) => void;
  onWorkflowFailed?: (info: { error: Error; phase: string }) => void;
  onSidebarUpdate?: (info: { title?: string; indicator?: string; phases?: Array<{ id: string; label: string; icon: string }> }) => void;
}

export type TurnContentBlock =
  | { type: 'text'; text: string }
  | { type: 'thinking'; thinking: string; redacted?: boolean }
  | { type: 'toolCall'; id: string; name: string; arguments: Record<string, unknown> };

export interface AgentStatusCallbacks {
  onTurnStart?: (info: { agentId: string; turn: number }) => void;
  onTurnEnd?: (info: {
    agentId: string;
    turn: number;
    tokens?: { input: number; output: number };
    contentBlocks?: TurnContentBlock[];
  }) => void;
  onToolCallStart?: (info: { agentId: string; toolName: string; toolCallId: string; arguments: Record<string, unknown> }) => void;
  onToolCallEnd?: (info: { agentId: string; toolName: string; toolCallId: string; isError: boolean }) => void;
}

export type StatusCallbacks = WorkflowStatusCallbacks & AgentStatusCallbacks;

// ─── Agent Loop Result ──────────────────────────────────────────────────────
export interface AgentLoopResult<T> {
  result: T;
  attempts: number;
  totalTokens: { input: number; output: number };
}

// ─── Workflow Run Options ──────────────────────────────────────────────────
export interface WorkflowRunOptions {
  cwd: string;
  workDir: string;
  maxConcurrentTasks?: number;
  apiKeys?: Record<string, string>;
  onStatus?: StatusCallbacks;
  /** Abort signal for cooperative cancellation (e.g. SIGINT) */
  signal?: AbortSignal;
}

// ─── Workflow Entry ───────────────────────────────────────────────────────
export interface WorkflowEntry {
  name: string;
  source: 'local' | 'global';
  path: string;
}

// ─── Workflow Module ────────────────────────────────────────────────────────
export interface WorkflowModule {
  run(taskPrompt: string, options: WorkflowRunOptions): Promise<void>;
  name?: string;
  description?: string;
}

// ─── Harness Creation ───────────────────────────────────────────────────────
export interface HarnessCreationOptions {
  profile: AgentProfile;
  cwd: string;
  apiKeys?: Record<string, string>;
  onAgentStatus?: AgentStatusCallbacks;
  sessionDir?: string;
  resumeSessionPath?: string;
}

import { afterEach, beforeEach, describe, expect, it, mock } from 'bun:test';
import { join } from 'node:path';
import { clearWorkflowCache, loadWorkflow } from '../../src/core/workflow-loader.js';

// ─── Helpers ──────────────────────────────────────────────────────────────

/**
 * Returns the project root as the cwd so that resolveWorkflowsDirs
 * points at .engin/workflows which contains the develop workflow.
 */
function projectCwd(): string {
  return join(import.meta.dirname, '..', '..');
}

beforeEach(() => {
  clearWorkflowCache();
});

// ─── Tests ──────────────────────────────────────────────────────────────────

describe('develop workflow', () => {
  it('loads via loadWorkflow and returns a WorkflowModule', async () => {
    const cwd = projectCwd();

    const mod = await loadWorkflow('develop', cwd);

    expect(mod).toBeDefined();
    expect(typeof mod.run).toBe('function');
  });

  it('default export has name and description', async () => {
    // Directly import the module to check default export shape
    const mod = await import(
      join(import.meta.dirname, '..', '..', '.engin', 'workflows', 'develop', 'main.ts')
    );
    const workflow = mod.default;

    expect(workflow).toBeDefined();
    expect(workflow.name).toBe('develop');
    expect(workflow.description).toBe('Multi-agent development workflow');
    expect(typeof workflow.run).toBe('function');
  });

  it('run() calls lifecycle callbacks in order', async () => {
    const cwd = projectCwd();

    const mod = await loadWorkflow('develop', cwd);

    const callOrder: string[] = [];
    const onStatus = {
      onWorkflowStart: mock((info: { taskPrompt: string }) => {
        callOrder.push('onWorkflowStart');
        expect(info.taskPrompt).toBe('test prompt');
        expect(info.resumed).toBe(false);
        expect(info.workDir).toBe('/tmp/work');
      }),
      onPhaseStart: mock((info: { phase: string }) => {
        callOrder.push(`onPhaseStart:${info.phase}`);
      }),
      onPhaseComplete: mock((info: { phase: string }) => {
        callOrder.push(`onPhaseComplete:${info.phase}`);
      }),
      onSidebarUpdate: mock((info: { title?: string; indicator?: string; phases?: unknown }) => {
        if (info.phases) {
          callOrder.push('onSidebarUpdate:phases');
        }
        if (info.title || info.indicator) {
          callOrder.push(`onSidebarUpdate:${info.indicator ?? 'title'}`);
        }
      }),
      onAgentSpawn: mock(() => {
        callOrder.push('onAgentSpawn');
      }),
      onAgentComplete: mock(() => {
        callOrder.push('onAgentComplete');
      }),
      onWorkflowComplete: mock((info: { totalDurationMs: number; agentCount: number }) => {
        callOrder.push('onWorkflowComplete');
        expect(info.agentCount).toBe(1);
      }),
      onTurnStart: mock(() => {}),
      onTurnEnd: mock(() => {}),
      onToolCallStart: mock(() => {}),
      onToolCallEnd: mock(() => {}),
    };

    await mod.run('test prompt', {
      cwd,
      workDir: '/tmp/work',
      onStatus,
    });

    // Verify the expected lifecycle order
    expect(callOrder).toContain('onSidebarUpdate:phases');
    expect(callOrder).toContain('onWorkflowStart');
    expect(callOrder).toContain('onPhaseStart:initialization');
    expect(callOrder).toContain('onPhaseComplete:initialization');
    expect(callOrder).toContain('onPhaseStart:scouting');
    expect(callOrder).toContain('onPhaseComplete:scouting');
    expect(callOrder).toContain('onPhaseStart:scouting_review');
    expect(callOrder).toContain('onPhaseComplete:scouting_review');
    expect(callOrder).toContain('onPhaseStart:planning');
    expect(callOrder).toContain('onPhaseComplete:planning');
    expect(callOrder).toContain('onPhaseStart:plan_review');
    expect(callOrder).toContain('onPhaseComplete:plan_review');
    expect(callOrder).toContain('onPhaseStart:implementing');
    expect(callOrder).toContain('onPhaseComplete:implementing');
    expect(callOrder).toContain('onPhaseStart:final_review');
    expect(callOrder).toContain('onPhaseComplete:final_review');
    expect(callOrder).toContain('onPhaseStart:done');
    expect(callOrder).toContain('onPhaseComplete:done');
    expect(callOrder).toContain('onWorkflowComplete');

    expect(onStatus.onWorkflowComplete).toHaveBeenCalledTimes(1);
  });

  it('generates a title using the agent when a profile is available', async () => {
    const cwd = projectCwd();

    const mod = await loadWorkflow('develop', cwd);

    let capturedTitle: string | undefined;
    const onStatus = {
      onSidebarUpdate: mock((info: { title?: string }) => {
        if (info.title) capturedTitle = info.title;
      }),
      onWorkflowStart: mock(() => {}),
      onPhaseStart: mock(() => {}),
      onPhaseComplete: mock(() => {}),
      onAgentSpawn: mock(() => {}),
      onAgentComplete: mock(() => {}),
      onWorkflowComplete: mock(() => {}),
      onTurnStart: mock(() => {}),
      onTurnEnd: mock(() => {}),
      onToolCallStart: mock(() => {}),
      onToolCallEnd: mock(() => {}),
    };

    const testPrompt = 'Write a REST API for user management with authentication';
    await mod.run(testPrompt, {
      cwd,
      workDir: '/tmp/work',
      onStatus,
    });

    // Since there are profiles available, a real AI-generated title should be returned
    expect(capturedTitle).toBeDefined();
    expect(capturedTitle!.length).toBeGreaterThan(0);
    // The title should NOT be the fallback truncated prompt
    expect(capturedTitle).not.toBe(testPrompt.slice(0, 50) + '...');
    // The title should be concise (3-6 words typically)
    const words = capturedTitle!.split(' ');
    expect(words.length).toBeGreaterThanOrEqual(1);
    expect(words.length).toBeLessThanOrEqual(15); // generous bound for real AI output
  });

  it('handles missing onStatus gracefully (no callbacks)', async () => {
    const cwd = projectCwd();

    const mod = await loadWorkflow('develop', cwd);

    // Should not throw when onStatus is entirely absent
    await expect(
      mod.run('test prompt', {
        cwd,
        workDir: '/tmp/work',
      }),
    ).resolves.toBeUndefined();
  });

  it('handles partial onStatus with some callbacks missing', async () => {
    const cwd = projectCwd();

    const mod = await loadWorkflow('develop', cwd);

    // Only provide onWorkflowStart and onWorkflowComplete
    const calls: string[] = [];
    await mod.run('test prompt', {
      cwd,
      workDir: '/tmp/work',
      onStatus: {
        onWorkflowStart: mock(() => calls.push('start')),
        onWorkflowComplete: mock(() => calls.push('complete')),
      },
    });

    expect(calls).toEqual(['start', 'complete']);
  });

  it('passes DEVELOP_PHASES to onSidebarUpdate', async () => {
    const cwd = projectCwd();

    const mod = await loadWorkflow('develop', cwd);

    let capturedPhases: unknown;
    const onStatus = {
      onSidebarUpdate: mock((info: { phases?: unknown }) => {
        if (info.phases) capturedPhases = info.phases;
      }),
      onWorkflowStart: mock(() => {}),
      onPhaseStart: mock(() => {}),
      onPhaseComplete: mock(() => {}),
      onWorkflowComplete: mock(() => {}),
    };

    await mod.run('test prompt', {
      cwd,
      workDir: '/tmp/work',
      onStatus,
    });

    expect(capturedPhases).toBeDefined();
    expect(Array.isArray(capturedPhases)).toBe(true);
    const phases = capturedPhases as Array<{ id: string; label: string; icon: string }>;
    expect(phases).toHaveLength(8);
    expect(phases[0].id).toBe('initialization');
    expect(phases[0].label).toBe('Initialization');
    expect(phases[0].icon).toBe('🔧');
    expect(phases[7].id).toBe('done');
    expect(phases[7].label).toBe('Done');
    expect(phases[7].icon).toBe('🎉');
  });

  it('invokes agent spawn/complete callbacks during initialization', async () => {
    const cwd = projectCwd();

    const mod = await loadWorkflow('develop', cwd);

    let agentSpawnCalled = false;
    let agentCompleteCalled = false;
    let capturedAgentId: string | undefined;
    let capturedProfile: string | undefined;

    const onStatus = {
      onWorkflowStart: mock(() => {}),
      onPhaseStart: mock(() => {}),
      onPhaseComplete: mock(() => {}),
      onAgentSpawn: mock((info: { agentId: string; profile: string }) => {
        agentSpawnCalled = true;
        capturedAgentId = info.agentId;
        capturedProfile = info.profile;
      }),
      onAgentComplete: mock((info: { agentId: string; profile: string }) => {
        agentCompleteCalled = true;
        expect(info.agentId).toBe(capturedAgentId);
        expect(info.profile).toBe(capturedProfile);
      }),
      onSidebarUpdate: mock(() => {}),
      onWorkflowComplete: mock(() => {}),
      onTurnStart: mock(() => {}),
      onTurnEnd: mock(() => {}),
      onToolCallStart: mock(() => {}),
      onToolCallEnd: mock(() => {}),
    };

    await mod.run('Build a CLI tool', {
      cwd,
      workDir: '/tmp/work',
      onStatus,
    });

    // With profiles available, agent spawn and complete should be called
    expect(agentSpawnCalled).toBe(true);
    expect(agentCompleteCalled).toBe(true);
    expect(capturedAgentId).toBe('title-generator');
    expect(capturedProfile).toBeDefined();
  });
});

// ─── Shared Utilities ────────────────────────────────────────────────────────

/**
 * Validates a workflow name, throwing if it contains path separators or "..".
 */
export function validateWorkflowName(name: string): void {
  if (name.includes('/') || name.includes('\\') || name.includes('..')) {
    throw new Error(`Invalid workflow name: "${name}". Names must not contain path separators or "..".`);
  }
}

/**
 * Returns true when `err` is a non-null object with a `code` property
 * equal to `'ENOENT'`.
 */
export function isEnoentError(err: unknown): boolean {
  return typeof err === 'object' && err !== null && 'code' in err && (err as { code: string }).code === 'ENOENT';
}

/**
 * Extracts a human-readable error message from an unknown thrown value.
 */
export function safeErrorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

/** Default tool names used by the harness when no include/exclude list is specified. */
export const DEFAULT_TOOLS: readonly string[] = Object.freeze(['read', 'bash', 'edit', 'write', 'grep', 'find', 'ls']);

import type { AgentProfile } from '../../src/core/types.js';

/**
 * Creates an AgentProfile with sensible defaults.
 */
export function makeProfile(overrides?: Partial<AgentProfile>): AgentProfile {
  return {
    id: 'test-agent',
    name: 'Test Agent',
    provider: 'openai',
    model: 'gpt-4o',
    thinkingLevel: 'medium',
    systemPrompt: 'You are a test agent.',
    excludeTools: [],
    includeTools: [],
    ...overrides,
  };
}

// ─── Harness Factory ────────────────────────────────────────────────────────
import { getModel } from '@earendil-works/pi-ai';
import type { AgentSession } from '@earendil-works/pi-coding-agent';
import {
  type AgentSessionEvent,
  AuthStorage,
  createAgentSession,
  DefaultResourceLoader,
  SessionManager,
} from '@earendil-works/pi-coding-agent';

import { loadProfile } from './profile.js';
import type { HarnessCreationOptions, TurnContentBlock } from './types.js';
import { DEFAULT_TOOLS } from './utils.js';

// ─── Agent Event Types ──────────────────────────────────────────────────────

/* eslint-disable @typescript-eslint/no-explicit-any */
type AgentLevelEvent =
  | { type: 'turn_start' }
  | { type: 'turn_end'; message: { role: string; content?: any[]; usage?: { input: number; output: number } } }
  | { type: 'tool_execution_start'; toolName: string; toolCallId: string; args?: Record<string, unknown> }
  | { type: 'tool_execution_end'; toolName: string; toolCallId: string; isError: boolean };
/* eslint-enable @typescript-eslint/no-explicit-any */

// ─── createHarness ──────────────────────────────────────────────────────────

/**
 * Create an {@link AgentSession} wired to an in-memory session.
 *
 * Resolution steps:
 * 1. Resolve the model via {@link getModel}; throw if the provider/model
 *    combination is unknown.
 * 2. Create an {@link AuthStorage} via {@link AuthStorage.create} (loads
 *    credentials from `~/.pi/agent/auth.json`) and apply any caller-supplied
 *    `apiKeys` as runtime overrides.
 * 3. Build the tool allowlist/denylist from the profile configuration.
 * 4. Create a {@link DefaultResourceLoader} with the profile's system prompt.
 * 5. Construct the session via {@link createAgentSession}.
 * 6. Optionally subscribe to agent status callbacks.
 */
export async function createHarness(
  options: HarnessCreationOptions,
): Promise<{ session: AgentSession; sessionId: string; dispose: () => void }> {
  const { profile, cwd, apiKeys, onAgentStatus } = options;

  // 1. Model
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const model = getModel(profile.provider as any, profile.model as any);
  if (!model) {
    throw new Error(
      `Unknown model "${profile.model}" for provider "${profile.provider}". ` +
        `Check the provider and model identifiers.`,
    );
  }

  // 2. Auth storage — reads ~/.pi/agent/auth.json for stored credentials
  const authStorage = AuthStorage.create();
  if (apiKeys) {
    for (const [provider, key] of Object.entries(apiKeys)) {
      authStorage.setRuntimeApiKey(provider, key);
    }
  }

  // 3. Tools
  let builtTools: string[];
  if (profile.includeTools && profile.includeTools.length > 0) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    builtTools = [...DEFAULT_TOOLS].filter((name) => profile.includeTools!.includes(name));
  } else {
    builtTools = [...DEFAULT_TOOLS];
  }
  if (profile.excludeTools && profile.excludeTools.length > 0) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    builtTools = builtTools.filter((name) => !profile.excludeTools!.includes(name));
  }

  // 4. Resource loader
  const resourceLoader = new DefaultResourceLoader({
    cwd,
    agentDir: cwd,
    systemPromptOverride: () => profile.systemPrompt,
  });
  await resourceLoader.reload();

  // 5. Session
  let sessionManager;
  if (options.resumeSessionPath) {
    sessionManager = SessionManager.open(options.resumeSessionPath, undefined, cwd);
  } else if (options.sessionDir) {
    sessionManager = SessionManager.create(cwd, options.sessionDir);
  } else {
    sessionManager = SessionManager.inMemory(cwd);
  }
  const { session } = await createAgentSession({
    sessionManager,
    model,
    thinkingLevel: profile.thinkingLevel,
    tools: builtTools,
    resourceLoader,
    authStorage,
  });

  const sessionId = session.sessionId;

  // 6. Subscribe to agent status callbacks (if any handlers provided)
  let unsubscribe: (() => void) | undefined;
  if (
    onAgentStatus &&
    (onAgentStatus.onTurnStart ||
      onAgentStatus.onTurnEnd ||
      onAgentStatus.onToolCallStart ||
      onAgentStatus.onToolCallEnd)
  ) {
    let turnCount = 0;
    unsubscribe = session.subscribe((event: AgentSessionEvent) => {
      const e = event as AgentLevelEvent;
      if (e.type === 'turn_start') {
        onAgentStatus.onTurnStart?.({
          agentId: sessionId,
          turn: ++turnCount,
        });
      } else if (e.type === 'turn_end') {
        const isAssistant = e.message?.role === 'assistant';
        const usage = isAssistant ? e.message?.usage : undefined;
        let contentBlocks: TurnContentBlock[] | undefined;
        if (isAssistant && e.message.content) {
          contentBlocks = [];
          // Map only the block types supported by TurnContentBlock.
          // Unrecognized types (e.g., future upstream additions) are intentionally skipped.
          for (const block of e.message.content) {
            if (block.type === 'text') {
              contentBlocks.push({ type: 'text', text: block.text });
            } else if (block.type === 'thinking') {
              contentBlocks.push({ type: 'thinking', thinking: block.thinking, redacted: block.redacted });
            } else if (block.type === 'toolCall') {
              contentBlocks.push({ type: 'toolCall', id: block.id, name: block.name, arguments: block.arguments });
            }
          }
        }
        onAgentStatus.onTurnEnd?.({
          agentId: sessionId,
          turn: turnCount,
          tokens: usage ? { input: usage.input, output: usage.output } : undefined,
          contentBlocks,
        });
      } else if (e.type === 'tool_execution_start') {
        onAgentStatus.onToolCallStart?.({
          agentId: sessionId,
          toolName: e.toolName,
          toolCallId: e.toolCallId,
          arguments: e.args ?? {},
        });
      } else if (e.type === 'tool_execution_end') {
        onAgentStatus.onToolCallEnd?.({
          agentId: sessionId,
          toolName: e.toolName,
          toolCallId: e.toolCallId,
          isError: e.isError ?? false,
        });
      }
    });
  }

  const dispose = () => {
    unsubscribe?.();
    session.dispose();
  };

  return { session, sessionId, dispose };
}

// ─── createHarnessFromProfile ───────────────────────────────────────────────

/**
 * Convenience wrapper that loads an {@link AgentProfile} from a directory
 * and delegates to {@link createHarness}.
 */
export async function createHarnessFromProfile(
  dirPath: string,
  profileId: string,
  options: Omit<HarnessCreationOptions, 'profile'>,
): Promise<{ session: AgentSession; sessionId: string; dispose: () => void }> {
  const profile = await loadProfile(dirPath, profileId);
  return createHarness({ ...options, profile });
}

// ─── Agent Loop Utilities ──────────────────────────────────────────────────
import type { AgentSession } from '@earendil-works/pi-coding-agent';
import type { ZodType } from 'zod';
import { createHarness } from './harness-factory.js';
import { promptForStructured, type PromptableHarness } from './structured-output.js';
import type { AgentLoopResult, HarnessCreationOptions } from './types.js';

// ─── Internal Helpers ─────────────────────────────────────────────────────

/**
 * Create sessions for every config sequentially, rolling back any
 * already-created sessions if one fails.
 */
async function createSessionsWithCleanup(
  configs: HarnessCreationOptions[],
): Promise<Awaited<ReturnType<typeof createHarness>>[]> {
  const results: Awaited<ReturnType<typeof createHarness>>[] = [];
  try {
    for (const config of configs) {
      results.push(await createHarness(config));
    }
  } catch (err) {
    for (const r of results) {
      r.dispose?.();
    }
    throw err;
  }
  return results;
}

// ─── agentLoopUntil ────────────────────────────────────────────────────────

export interface AgentLoopUntilOptions {
  maxAttempts?: number;
}

/**
 * Repeatedly prompt the session until `conditionFn` returns `true` or
 * `maxAttempts` is exhausted.
 *
 * @param session    Object with `prompt(text)` and `getLastAssistantText()` methods.
 * @param promptFn   Called with `(attempt, lastText?)` to build each prompt.
 * @param conditionFn  Return `true` to stop the loop. Receives the last assistant text.
 * @param options    `{ maxAttempts }` — default 10.
 * @returns The final text and the number of attempts made.
 */
export async function agentLoopUntil(
  session: PromptableHarness,
  promptFn: (attempt: number, lastText?: string) => string,
  conditionFn: (lastText: string | undefined) => boolean,
  options?: AgentLoopUntilOptions,
): Promise<{ lastText: string | undefined; attempts: number }> {
  const maxAttempts = options?.maxAttempts ?? 10;
  let lastText: string | undefined;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const prompt = promptFn(attempt, lastText);
    await session.prompt(prompt);
    lastText = session.getLastAssistantText();
    if (conditionFn(lastText)) {
      return { lastText, attempts: attempt };
    }
  }

  throw new Error(`agentLoopUntil: condition not met after ${maxAttempts} attempts`);
}

// ─── retryAgentUntil ───────────────────────────────────────────────────────

/**
 * Convenience wrapper around {@link promptForStructured} that returns an
 * {@link AgentLoopResult} envelope.
 *
 * Token tracking is not available through this wrapper; `totalTokens` is
 * set to zero.
 */
export async function retryAgentUntil<T>(
  session: PromptableHarness,
  prompt: string,
  schema: ZodType<T>,
  options?: { maxRetries?: number },
): Promise<AgentLoopResult<T>> {
  const result = await promptForStructured(
    session,
    prompt,
    schema,
    options?.maxRetries !== undefined ? { maxRetries: options.maxRetries } : undefined,
  );

  return {
    result,
    attempts: options?.maxRetries ?? 3,
    // TODO: Pass actual token counts from the session instead of hardcoding zeros
    totalTokens: { input: 0, output: 0 },
  };
}

// ─── parallelAgents ────────────────────────────────────────────────────────

export interface ParallelAgentOptions {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  schema?: ZodType<any>;
  maxRetries?: number;
}

/**
 * Create sessions for every config in parallel, then run prompts in parallel
 * via `Promise.allSettled`.
 *
 * When `options.schema` is provided each prompt is parsed through
 * {@link promptForStructured}; otherwise the last assistant text is returned.
 */
export async function parallelAgents<T = string | undefined>(
  configs: HarnessCreationOptions[],
  promptFn: (session: AgentSession, index: number) => string,
  options?: ParallelAgentOptions,
): Promise<PromiseSettledResult<T>[]> {
  // 1. Create sessions sequentially so partial failures dispose already-created sessions
  const sessionResults = await createSessionsWithCleanup(configs);

  // 2. Run prompts
  try {
    const results = await Promise.allSettled(
      sessionResults.map(async ({ session }, i) => {
        const prompt = promptFn(session, i);
        if (options?.schema) {
          return promptForStructured(
            session,
            prompt,
            options.schema,
            options.maxRetries !== undefined ? { maxRetries: options.maxRetries } : undefined,
          ) as Promise<T>;
        }
        await session.prompt(prompt);
        return session.getLastAssistantText() as unknown as T;
      }),
    );

    return results;
  } finally {
    for (const result of sessionResults) {
      result.dispose?.();
    }
  }
}

// ─── sequentialAgents ──────────────────────────────────────────────────────

export interface SequentialAgentOptions {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  schema?: ZodType<any>;
  maxRetries?: number;
}

/**
 * Create sessions one at a time, run prompts sequentially, and dispose
 * each session after use. Throws on the first failure.
 */
export async function sequentialAgents<T = string | undefined>(
  configs: HarnessCreationOptions[],
  promptFn: (session: AgentSession, index: number) => string,
  options?: SequentialAgentOptions,
): Promise<T[]> {
  const results: T[] = [];
  for (let i = 0; i < configs.length; i++) {
    const { session, dispose } = await createHarness(configs[i]);
    try {
      const promptText = promptFn(session, i);
      if (options?.schema) {
        results.push(
          (await promptForStructured(
            session,
            promptText,
            options.schema,
            options.maxRetries !== undefined ? { maxRetries: options.maxRetries } : undefined,
          )) as T,
        );
      } else {
        await session.prompt(promptText);
        results.push(session.getLastAssistantText() as unknown as T);
      }
    } finally {
      dispose?.();
    }
  }
  return results;
}

